insert into bundles (id, item_type, level, generator_model, generated_at) values ('sougou_dokkai_J2_002', 'sougou_dokkai', 'J2', 'manual-load', '2026-10-10T04:55:32+00:00') on conflict (id) do update set item_type = excluded.item_type, level = excluded.level, generator_model = excluded.generator_model, generated_at = excluded.generated_at;
insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('3d4b27da34', 'sougou_dokkai_J2_002', 'sougou_dokkai', 'J2', 'project_update+staff_to_client+infer_intent@J2', 'project_update', 'staff_to_client', 'infer_intent', 'written', null, null, null, '進捗報告で本当に頼みたいこと', '松本さんがこの報告書で最も伝えたいことは何ですか。', 0, '工程表と課題を合わせて読むと、画面設計書の確認結果がまだ届いておらず、届いてから開発の準備に2営業日かかる。開発は10月19日に始める予定で、本番の12月7日は北斗運輸の希望で動かせない。だから、確認を早く返してほしいというのが松本さんの用件で、最後の「ご確認の状況について、一度お聞かせいただけますと幸いです」はその控えめな言い方である。要件定義の遅れは取り戻したと書いてあるが、相手に求めることではない。本番をずらす話は書かれておらず、むしろ動かさない前提である。確認を待っているのは画面設計書で、要件定義はすでに完了している。', 'The design review is overdue, development needs two business days after it, and the go-live date cannot move, so the polite closing line is really a request to return the review quickly.', '[{"term": "進捗", "reading": "しんちょく", "meaning": "progress"}, {"term": "工程表", "reading": "こうていひょう", "meaning": "project schedule"}, {"term": "本番切り替え", "reading": "ほんばんきりかえ", "meaning": "go-live cutover"}, {"term": "繁忙期", "reading": "はんぼうき", "meaning": "busy season"}]', '[{"template": "progress_report", "title": "配送管理システム更新 進捗報告（第6回）", "meta": [{"label": "報告者", "value": "ひかりソフト 開発部 松本"}, {"label": "報告日", "value": "10月12日"}, {"label": "案件", "value": "北斗運輸様 配送管理システム更新"}], "blocks": [{"type": "paragraph", "text": "北斗運輸株式会社 情報システム部 西田様　いつもお世話になっております。今週の進捗をご報告いたします。先週お伝えした要件定義の遅れは、作業の順番を入れ替えることで取り戻すことができました。"}, {"type": "table", "caption": "工程表", "columns": ["工程", "予定", "状況"], "rows": [["要件定義", "9月30日まで", "完了"], ["画面設計", "10月9日まで", "設計書をお送り済み・ご確認待ち"], ["開発", "10月19日〜11月13日", "未着手"], ["テスト", "11月16日〜11月27日", "未着手"], ["本番切り替え", "12月7日", "未着手"]]}, {"type": "heading", "level": 2, "text": "課題と対応"}, {"type": "bullets", "items": ["画面設計書は9月30日にお送りし、10月9日にご確認の結果をいただく予定でしたが、まだいただいておりません。", "ご確認の結果をいただいてから開発の準備を整えるまでに、2営業日を見込んでおります。", "本番切り替えの12月7日は、御社の年末の繁忙期に入る前にとのご意向を伺っておりますので、動かさない前提で計画しております。"]}, {"type": "paragraph", "text": "ご多忙のところ恐縮ですが、ご確認の状況について、一度お聞かせいただけますと幸いです。"}]}]', '[]', null, null) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('cf4afe8905', 'sougou_dokkai_J2_002', 'sougou_dokkai', 'J2', 'internal_change+superior_to_subordinate+infer_risk@J2', 'internal_change', 'superior_to_subordinate', 'infer_risk', 'written', null, null, null, '通知の期限とシステムの開始日', 'この通知について、総務部に確認すべき問題は何ですか。', 1, '通知の最初に、予約システムは11月2日の朝9時から使え、それより前は画面も開けないと書いてある。ところが、紙の予約表の11月分は10月30日までにシステムへ入れ直すよう求めていて、入れ直されない予約は無効になる。期限の時点ではまだシステムが使えないので、このままでは誰も入れ直せず、11月分の予約がすべて無効になってしまう。これが総務部に確認すべき問題である。10月中の予約は紙のままでよい。応接室を受付で予約するのは決まりで、問題ではない。使い方はマニュアルが社内ポータルにある。', 'The notice asks for November bookings to be re-entered by 30 October, but says the system cannot be opened until 2 November, so nobody can meet the deadline.', '[{"term": "予約表", "reading": "よやくひょう", "meaning": "booking sheet"}, {"term": "無効", "reading": "むこう", "meaning": "invalid, void"}, {"term": "回収", "reading": "かいしゅう", "meaning": "to collect (back)"}, {"term": "終業", "reading": "しゅうぎょう", "meaning": "end of the working day"}]', '[{"template": "memo_notice", "title": "会議室の予約方法の変更について", "meta": [{"label": "発信者", "value": "総務部長 小川"}, {"label": "発信日", "value": "10月20日"}, {"label": "対象", "value": "全社員"}], "blocks": [{"type": "paragraph", "text": "これまで各階の紙の予約表で受け付けていた会議室の予約を、新しい予約システムに切り替えます。予約システムは11月2日（月）の朝9時から利用できるようになります。準備の都合上、それより前には画面を開くことができませんので、ご注意ください。"}, {"type": "heading", "level": 2, "text": "全社員にお願いすること"}, {"type": "numbered", "items": ["11月2日以降の会議室の利用は、すべて予約システムから予約してください。", "紙の予約表にすでに記入してある11月分の予約は、10月30日（金）までに、予約した本人が予約システムに入れ直してください。入れ直されていない予約は無効になります。", "10月中の予約は、これまでどおり紙の予約表で受け付けます。"]}, {"type": "heading", "level": 2, "text": "部署ごとのお願い"}, {"type": "bullets", "items": ["営業部：来客用の応接室は、これまでどおり受付で予約してください。予約システムでは扱いません。", "総務部：紙の予約表は、10月30日の終業後に各階から回収します。"]}, {"type": "paragraph", "text": "予約システムの使い方は、社内ポータルの「総務部からのお知らせ」にマニュアルを掲載しています。"}]}]', '[]', null, null) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
